#!/bin/sh
set -eu
cd /seed
# Copy missing files individually: recursive cp -n may skip an existing destination directory.
# The uploaded filenames are generated by the application; initial seed files are immutable.
find . -type f | while IFS= read -r image; do
  target="/uploads/$image"
  mkdir -p "$(dirname "$target")"
  if [ ! -e "$target" ]; then
    cp -p "$image" "$target"
  fi
done
